import {cartSummary,UNLISTED_IDS} from './cart.mjs?v=20261028-checkout-1';
export const PROFILE_LIMITS={name:80,address:180,city:60,phone:30,contact:80,notes:240};
const clean=(v,n)=>String(v??'').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g,'').trim().slice(0,n);
export function normalizePharmacy(raw={}){return Object.fromEntries(Object.entries(PROFILE_LIMITS).map(([k,n])=>[k,clean(raw?.[k],n)]));}
export function pharmacyErrors(raw){const p=normalizePharmacy(raw);return[p.name?'':'أدخل اسم الصيدلية.',p.address?'':'أدخل عنوان الصيدلية بالتفصيل.'].filter(Boolean);}
export function createInvoice(cart,products,profile,{now=new Date(),id,previousId=''}={}){const pharmacy=normalizePharmacy(profile);const errors=pharmacyErrors(pharmacy);if(errors.length)throw Error(errors.join(' '));const s=cartSummary(cart,products);if(!s.items.length)throw Error('أضف صنفًا صالحًا إلى السلة أولًا.');const day=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Damascus',year:'numeric',month:'2-digit',day:'2-digit'}).format(now).replaceAll('-','');return{version:1,id:id||`AS-${day}-${Array.from(crypto.getRandomValues(new Uint8Array(6)),b=>b.toString(16).padStart(2,'0')).join('').toUpperCase()}`,createdAt:now.toISOString(),previousId:clean(previousId,60),pharmacy,items:s.items.map(({product:p,qty})=>({id:p.id,ar:p.ar,en:p.en,qty,unitPrice:p.price,total:qty*p.price})),count:s.count,total:s.total,currency:'SYP',receipt:{warehouseName:'',pharmacyName:'',date:'',notes:'',warehouseSignature:'',pharmacySignature:'',updatedAt:''}};}
export function validateInvoice(x){if(!x||x.version!==1||!/^AS-[A-Z0-9-]{8,60}$/.test(x.id)||!Number.isFinite(Date.parse(x.createdAt))||pharmacyErrors(x.pharmacy).length||!Array.isArray(x.items)||!x.items.length||x.items.length>400)return false;let total=0,count=0;const seen=new Set();for(const i of x.items){if(!i||!/^MED-\d+$/.test(i.id)||UNLISTED_IDS.includes(i.id)||seen.has(i.id)||typeof i.ar!=='string'||i.ar.length>300||typeof i.en!=='string'||i.en.length>300||!Number.isInteger(i.qty)||i.qty<1||i.qty>99||!Number.isSafeInteger(i.unitPrice)||i.unitPrice<=0||i.unitPrice>1000000000||i.total!==i.qty*i.unitPrice)return false;seen.add(i.id);total+=i.total;count+=i.qty;}return total===x.total&&count===x.count&&x.currency==='SYP';}
export function cleanReceipt(raw={}){const signature=v=>typeof v==='string'&&v.length<500000&&/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(v)?v:'';return{warehouseName:clean(raw.warehouseName,80),pharmacyName:clean(raw.pharmacyName,80),date:/^\d{4}-\d{2}-\d{2}$/.test(raw.date||'')?raw.date:'',notes:clean(raw.notes,300),warehouseSignature:signature(raw.warehouseSignature),pharmacySignature:signature(raw.pharmacySignature),updatedAt:clean(raw.updatedAt,40)};}
export function receiptErrors(raw){const r=cleanReceipt(raw);const any=r.warehouseName||r.pharmacyName||r.date||r.notes||r.warehouseSignature||r.pharmacySignature;if(!any)return[];return[r.date?'':'حدد تاريخ التسليم.',r.warehouseSignature&&!r.warehouseName?'أدخل اسم ممثل المستودع.':'',r.pharmacySignature&&!r.pharmacyName?'أدخل اسم مستلم الصيدلية.':''].filter(Boolean);}
export function receiptStatus(raw){const r=cleanReceipt(raw);if(r.warehouseSignature&&r.pharmacySignature&&r.warehouseName&&r.pharmacyName&&r.date)return'توقيعان محفوظان على الجهاز';if(r.warehouseSignature||r.pharmacySignature)return'توقيع واحد محفوظ';return'بانتظار التوقيع عند التسليم';}
export const invoiceDate=iso=>new Intl.DateTimeFormat('ar-SY',{timeZone:'Asia/Damascus',dateStyle:'medium',timeStyle:'short'}).format(new Date(iso));
export function normalizeOrderPharmacy(raw={}){return normalizePharmacy({name:raw?.name,address:raw?.address});}
